/* cppi::d83f7ae2fb9d1104ddb0e0e899b5f61948280d107138356afa208f482f5be375 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2024-05-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-03-03'
    ) a
where arrival_time = max_publish

/* cppi::d83f7ae2fb9d1104ddb0e0e899b5f61948280d107138356afa208f482f5be375 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2024-05-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-03-03'
    ) a
where arrival_time = max_publish

/* cppi::45aaf05b07128c2fe6b1f855302560393da55821971869d63486399bf3cb2291 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-29' and end_date = '2025-05-29')
and start_date = '2025-05-29' and end_date = '2025-05-29'

/* cppi::5c0dbb9085b51684fbb59c5acaae4bf4aab7832438cc6b9073b742eb511e43a8 */
SELECT "SUBCOL" AS "COL"
FROM (
  SELECT 1 AS "SUBCOL"
) "SUBQUERY"
GROUP BY 1

